import sys
from collections import defaultdict

class TrieNode:
    __slots__ = ['children', 'words']
    def __init__(self):
        self.children = {}
        self.words = []

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    idx = 0
    N = int(data[idx])
    idx += 1

    words = []
    for _ in range(N):
        words.append(data[idx])
        idx += 1

    root = TrieNode()

    for w in words:
        node = root
        for ch in reversed(w):
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            if w not in node.words:
                node.words.append(w)

    Q = int(data[idx])
    idx += 1

    results = []
    for _ in range(Q):
        s = data[idx]
        idx += 1

        node = root
        found = True
        for ch in reversed(s):
            if ch not in node.children:
                found = False
                break
            node = node.children[ch]

        if found and node.words:
            node.words.sort()
            results.append(node.words[0])
        else:
            results.append(s)

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
